#!/usr/bin/env python3
from pathlib import Path
import base64
import gzip

_PAYLOAD = """"""

_path = Path(__file__).resolve()
_source = gzip.decompress(base64.b64decode(_PAYLOAD)).decode("utf-8")
_path.write_text(_source, encoding="utf-8")
_scope = {"__name__": "__main__", "__file__": str(_path)}
exec(compile(_source, str(_path), "exec"), _scope)
